fn solve(x: i32) -> i32 {
    // Convert x to a string to easily extract the digit and its repetition count
    let x_str = x.to_string();
    let d = x_str.chars().next().unwrap(); // The digit as a char
    let k = x_str.len(); // The length of the number, which is k

    let mut score = 0;

    // Calculate the score for all boring apartment numbers before x
    for digit in 1..=9 {
        let digit_char = char::from_digit(digit, 10).unwrap();
        // For each digit, calculate the score for lengths 1 to 4
        for length in 1..=4 {
            if length < k || (length == k && digit_char <= d) {
                // Each number of length 'length' requires 'length' presses
                score += length;
            }
        }
    }

    // Add the score for the number x itself
    score += k; // x requires k presses

    score
}